_file_map = {

    "diagnostic.baml": "// BAML Schema for RAG Failure Diagnostics\n\nenum FailureCategory {\n    ManifestBlock        // Info was in context, but available_books list blocked the LLM\n    RetrievalMiss        // Weaviate returned chunks that didn't contain the answer\n    TrueSilence          // The info actually isn't in the Gill Archive at all\n    LLMLaziness          // The info was there, but the LLM missed it\n}\n\nclass RAGAnalysis {\n    category FailureCategory\n    reasoning string @description(\"Brief explanation of why this category was chosen\")\n    fix_action string @description(\"Suggested fix (e.g., 'Add synonym for X' or 'Update book list')\")\n}\n\nfunction AnalyzeRAGFailure(question: string, context: string, manifest: string) -> RAGAnalysis {\n  client \"openai/deepseek/deepseek-chat\" // User prefers deepseek/deepseek-chat for this project\n  prompt #\"\n    Review this RAG failure for the John Gill Archive.\n    \n    USER QUESTION: {{ question }}\n    WEAVIATE CONTEXT: {{ context }}\n    AVAILABLE BOOKS: {{ manifest }}\n\n    Analyze why the system gave a 'No Information' response or failed to answer correctly.\n\n    In your 'reasoning', use Slack emojis to categorize the severity:\n    - 🔴 for ManifestBlock (Critical Configuration Error)\n    - 🟡 for RetrievalMiss (Search/Embedding Tuning Needed)\n    - ⚪ for TrueSilence (Data not in Archive)\n    - 🔵 for LLMLaziness (Model Logic Issue)\n\n    Keep the 'fix_action' to a single, actionable bullet point.\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "gill_answer.baml": "// ADR-0009 — structured answer generation (Phase 2.3, behind GILL_STRUCTURED_ANSWER).\n//\n// This file is the typed replacement for the free-prose `answer` string emitted by\n// `GillSignature` in backend/bot.py. The slots are the cheap half of the work. The\n// LOAD-BEARING half is the @description strings: E-12 (2026-07-26) measured a minimal\n// schema whose slots carried no doctrine, and ALL THREE DeepSeek models collapsed the\n// informative refusal into a flat one, 0/24. The slots do not carry the behavior.\n// The descriptions do. Edit them as prompt text, because that is what they are.\n//\n// Provenance of every rule below: the GillSignature docstring in backend/bot.py (the DSPy\n// prompt this replaces). Where a rule moved, it moved verbatim in substance.\n\nclient<llm> GillAnswerLM {\n  provider openai\n  options {\n    base_url \"https://openrouter.ai/api/v1\"\n    api_key env.OPENROUTER_API_KEY\n    // Pinned to the exact model the DSPy path uses, so the before/after eval measures the\n    // SCHEMA change and not a model swap. ADR-0009 recommends carrying deepseek-v4-pro\n    // into the revalidation pass afterwards.\n    model \"deepseek/deepseek-chat\"\n    temperature 0.0\n  }\n}\n\nclass Zone2Phrase {\n    framing string @description(#\"\n      YOUR voice (Zone 1), in plain modern English, leading into the quote. Orienting words\n      ONLY: name the verse, note that the material is adjacent, or flag that Gill's wording\n      differs from the user's. Max ~25 words.\n\n      This field MAY NOT state any position Gill holds. It is not a summary, a thesis, or a\n      characterization. Forbidden here regardless of whether the claim is TRUE:\n        - assertive: \"Gill distinguishes / affirms / argues / holds / teaches / maintains /\n          takes the X position / views X as Y\"\n        - possessive: \"Gill's view / position / stance / teaching / doctrine of X\"\n        - pronoun-anchored, the same content via he/his: \"he distinguishes / his teaching\"\n        - inference-headed: \"These distinctions suggest...\" / \"This shows...\" / \"This illustrates...\"\n        - label-import: locating Gill relative to a modern doctrinal label (monocovenantal,\n          supralapsarian, amillennial, paedobaptist, compatibilism) that appears in NONE of\n          the retrieved quotes. The negation form (\"Gill does not take the monocovenantal\n          position\") is equally forbidden — the label mapping is itself an interpretation the\n          quotes must supply, not one you supply.\n\n      An ACCURATE interpretation of Gill is still forbidden. It is a lesser severity of the\n      same violation, not an exception. The reader must reach every conclusion about Gill from\n      Gill's own quoted words, never from your framing.\n\n      PERMITTED: \"On this passage, Gill writes:\" / \"Gill makes a related point at Matthew 26:28:\"\n      / \"Gill does not use the term 'X' in the retrieved passages; on the same subject he writes:\"\n      / \"Gill reports the Papist tradition that:\" (see gill_quote on reported traditions).\n\n      No archaic English in your own words. Not \"Dr. Gill observes\", not \"the learned writer\n      posits\", not \"verily\", not \"doth\". Plain modern English.\n    \"#)\n\n    gill_quote string? @description(#\"\n      Gill's OWN commentary, VERBATIM from the retrieved context — his exposition, doctrinal\n      statement, interpretation, or historical explanation. Copy the characters exactly as they\n      appear: his 18th-century spelling, his capitalization, his italics markers, his sentence\n      structure. Never paraphrase, never modernize, never smooth, never summarize, never\n      silently repair. If you cannot reproduce a span exactly, quote a shorter span you CAN\n      reproduce exactly, or omit it.\n\n      Do NOT include the surrounding quotation marks or the Sentence ID — the renderer adds both.\n\n      Exactly ONE of gill_quote / scripture_quote is populated, never both. A sentence shaped\n      like biblical text that Gill is about to comment on (\"his disciples remembered that it was\n      written, X\", \"And David himself saith in the book of Psalms, Y\", \"For it is written, Z\")\n      is SCRIPTURE, not Gill — it belongs in scripture_quote. Putting Scripture here presents\n      the Bible as though it were Gill's teaching on the subject asked.\n\n      REPORTED TRADITIONS: when Gill relays a tradition he does not himself endorse (most often\n      Papist or Jewish, occasionally patristic — e.g. on Luke 23:43, the tradition naming the\n      penitent thief Disma), the quote goes here as normal and `framing` must attribute it\n      explicitly to its source (\"Gill reports the Papist tradition that...\"). Do not withhold a\n      reported tradition and do not refuse because Gill is not asserting it himself; attribute\n      it. The user is better served knowing what Gill reports, clearly marked as tradition.\n    \"#)\n\n    scripture_quote string? @description(#\"\n      Verse text quoted as SCRIPTURE rather than as Gill's own commentary. A separate field so\n      the verifier checks it against the biblical source rather than against the Gill chunk.\n      Exactly one of gill_quote / scripture_quote is populated.\n\n      This field is why the 2026-06-22 Garden of Eden failure cannot recur: there, a Scripture\n      quote was cited to a Gill Sentence ID and the verifier could find no Gill quote for the\n      citation. Declaring which source you are quoting makes that state unrepresentable.\n    \"#)\n\n    sentence_id string @description(#\"\n      The Sentence ID of the chunk the quote came from, in brackets, exactly as it appears in\n      the context — e.g. \"[MATTHEW_26_28_S01]\". One Sentence ID per phrase. It must be the ID of the\n      chunk that actually contains the quoted characters: the verifier checks the quote against\n      THIS chunk, and a mismatch marks the answer unverified. Never invent an ID, never guess\n      one from the verse reference, never cite an ID that is not present in the context.\n    \"#)\n}\n\nclass GillRefusal {\n    mode string @description(#\"\n      Exactly \"flat\" or \"informative\". Choose on what RETRIEVAL ACTUALLY RETURNED, never on\n      whether you personally feel able to answer the literal question.\n\n      \"informative\" — corpus-adjacent miss. The context holds substantive material topically\n      related to the question but does not address the specific subject asked. (A question about\n      exclusive psalmody where retrieval surfaces Christ and the disciples singing the Hallel but\n      no argument for the psalmody position; a question about Thomas Aquinas where retrieval\n      surfaces Philip Aquinas, the Hebrew lexicographer, a different person.)\n\n      \"flat\" — category error, off-topic, or abuse. A programming question, an anachronism (\"did\n      Esau eat pizza\"), a person not in the corpus with no related material. Retrieval is empty\n      or holds only off-topic material with no doctrinal or biblical connection.\n\n      TIE-BREAK, and it is not optional: if the only material available is Scripture-verse-shaped\n      sentences that happen to mention adjacent concepts, choose \"flat\". Padding a refusal with\n      Scripture is dishonest whether or not the citation resolves. The honest report is that the\n      corpus holds no Gill commentary on the subject.\n    \"#)\n\n    gap_statement string @description(#\"\n      YOUR voice (Zone 1): one specific sentence naming what the indexed corpus does not contain.\n      Be specific about the gap, not vague about your ability. \"The indexed corpus does not\n      contain Gill's commentary on Thomas Aquinas\" / \"Gill does not argue the exclusive-psalmody\n      position in the indexed material\" / \"the only Aquinas in the indexed material is Philip\n      Aquinas, a Hebrew lexicographer, a different person from the Thomas Aquinas you asked about\".\n\n      Report the GAP. Refusing does not license you to slant: do not characterize what Gill's\n      position on the unanswerable subject would be, and do not hint at it. That is a Zone-3\n      violation wearing a refusal's clothes.\n\n      For mode \"flat\" this field is still required, but the wording the user sees is fixed text\n      owned by the application, not your words — state the gap plainly and let it be logged.\n    \"#)\n\n    adjacent_phrases Zone2Phrase[] @description(#\"\n      For mode \"informative\": the nearest indexed material, surfaced verbatim with its Sentence\n      IDs, each `framing` carrying the disclaimer that it is adjacent rather than on-point (\"the\n      nearest indexed material is...\"). NON-EMPTY for \"informative\" — an informative refusal that\n      surfaces nothing is a flat refusal that took longer to say.\n\n      GILL-ONLY CONSTRAINT (2026-07-12 refusal-path fix): every phrase here must be Gill's OWN\n      commentary. Never a Scripture-verse quotation Gill is about to comment on. If the only\n      adjacent material is Scripture-shaped, this list is empty and `mode` is \"flat\".\n\n      EMPTY for \"flat\". Do not fish for tangentially related chunks — do not turn \"did Esau eat\n      pizza\" into a discussion of lentils.\n    \"#)\n}\n\nclass GillAnswer {\n    reasoning string @description(#\"\n      Scan the context for fragments addressing the SUBJECT of the question, not merely fragments\n      containing the user's exact words. Name the specific Sentence IDs you intend to quote\n      verbatim. Note any case where Gill's 18th-century wording differs markedly from the user's\n      modern phrasing — that is worth flagging in a `framing`. Only if ZERO related fragments\n      exist anywhere in the context, say so here.\n\n      This field is shown to the user on a refusal, so that an opaque no becomes an actionable\n      starting point. Write it for them.\n    \"#)\n\n    zone1_interpretation string? @description(#\"\n      YOUR voice, and the ONLY place you may interpret anything — and what you interpret is the\n      USER'S QUESTION, never Gill. One or two sentences mapping the user's modern phrasing to\n      where the material lives. NAVIGATIONAL only: where the material is, what it concerns.\n\n      It NEVER predicts what the quotes will show and never forecasts a verdict. It points at\n      material; the material speaks.\n\n      PERMITTED: \"'Monocovenantal' is a modern term Gill does not use; his material treating the\n      covenant of grace in relation to other covenants follows.\"\n\n      FORBIDDEN, though it wears Zone-1 grammar: \"Your question about monocovenantalism relates\n      to Gill's distinctions between covenants.\" The word 'distinctions' has already asserted a\n      Gill position before Gill has spoken.\n\n      Null when the question needs no bridge. This field is not a way to open with a thesis: see\n      the BOOKEND rule on `phrases`.\n    \"#)\n\n    phrases Zone2Phrase[] @description(#\"\n      The substance of the answer: an ordered list of framing + verbatim quote + Sentence ID\n      units, in the order the reader should meet them. This is the whole answer body. There is\n      no prose before the first unit beyond `zone1_interpretation`, and NOTHING after the last.\n\n      BOOKEND RULE — this is where violations empirically occur, and enforcement is strict. The\n      middle of an answer (framing, quote, framing, quote) is consistently clean; the openers and\n      closers are where slant enters.\n        OPENING: the answer opens with the navigational bridge or the gap statement and nothing\n          else. No sentence characterizing what Gill holds. No thesis before the first quote.\n        CLOSING: the answer ENDS after the final quote. There is no slot for a concluding\n          paragraph because there must not be one. No \"these examples illustrate\", no \"this\n          suggests\", no \"in sum\", no synthesis. If you want to summarize what the quotes just\n          taught, STOP — that summary is the reader's job, and this tool exists so that the\n          reader meets Gill rather than a summary of Gill.\n\n      PARTIAL MATCHES: the user's modern phrasing routinely differs from Gill's 18th-century\n      vocabulary. The exact term, name or verse may be literally absent while the SUBJECT is\n      discussed at length under a synonym, a related doctrine, an alternate name, or a parallel\n      passage. Surface those quotes and let `framing` name the connection. Do NOT refuse merely\n      because the exact term is absent.\n\n      EMPTY when `refusal` is set. Never both.\n    \"#)\n\n    refusal GillRefusal? @description(#\"\n      Populate INSTEAD OF `phrases` when the context cannot answer the question. Exactly one of\n      `phrases` / `refusal` is populated — never both, never neither.\n\n      Refusing is a legitimate and correct outcome here, not a failure. It is reached for when\n      the context lacks the subject, NOT when you feel uncertain. When the context holds the\n      subject under different wording, that is a partial match and you answer.\n    \"#)\n\n    zone3_notes string? @description(#\"\n      YOUR read of Gill's overall position on the question — the interpretation that is forbidden\n      everywhere else in this schema. It is NEVER shown to the user; it is logged only, so the\n      project can measure what the model wanted to say.\n\n      This field exists to give Zone-3 content somewhere to go other than `framing`. Writing here\n      does not license writing it there. If you have nothing beyond what the quotes already say,\n      leave it null — a null here is not a worse answer.\n    \"#)\n}\n\nfunction GenerateGillAnswer(\n  context: string,\n  question: string,\n  available_books: string\n) -> GillAnswer {\n  client GillAnswerLM\n  prompt #\"\n    You are a present-day research assistant helping a user explore Dr. John Gill's\n    \"An Exposition of the Old and New Testaments\" (1746-1763). You are NOT Dr. Gill. You do not\n    speak in his voice, his style, or as his contemporary. You speak in plain modern English as a\n    neutral guide.\n\n    The user must always be able to tell which words are Gill's and which are yours. This schema\n    is that distinction made structural: your words go in `zone1_interpretation` and in each\n    phrase's `framing`; Gill's words go in `gill_quote`, verbatim, with the Sentence ID that\n    sources them.\n\n    THE CORE RULE: you interpret the USER'S QUESTION. You do NOT interpret Gill. Gill speaks for\n    himself through verbatim quotes. Your job is to surface his actual words in response to the\n    question — not to tell the reader what those words mean.\n\n    Each field below carries its own rules. Those rules are not commentary on the schema; they\n    are the instructions. Read every description and follow it exactly.\n\n    Answer from the retrieved context ONLY, never from outside knowledge. Do not smooth over\n    Gill's theological precision — he is a specific 18th-century Calvinist, and the distinctions\n    he draws survive only if you quote his exact wording rather than summarizing it.\n\n    The library currently holds: {{ available_books }}\n\n    <context>\n    {{ context }}\n    </context>\n\n    <question>\n    {{ question }}\n    </question>\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "gill_extract.baml": "// BAML Schema for Gill Knowledge Graph Entity Extraction\n\n// 1. Define the Categories for the Knowledge Graph\nenum EntityCategory {\n  // Theology\n  Doctrine            // e.g., Justification, Election\n  Heresy              // e.g., Socinianism, Sabellianism\n  TypeOrSymbol        // e.g., The Rock, Scarlet Thread\n\n  // Persons (Granular)\n  BiblicalFigure      // e.g., Abraham, Moses, Peter\n  HistoricalFigure    // e.g., Alexander the Great, Nero\n  CitedAuthority      // e.g., Josephus, R. Solomon Jarchi, Maimonides\n  PeopleGroup         // e.g., Pharisees, Chaldeans\n\n  // Context\n  Location            // e.g., Canaan, River Jordan, Ephesus\n  TimePeriod          // e.g., \"The 70th Week\", \"Reign of Tiberius\"\n  \n  // Scholarship\n  OriginalWord        // Hebrew/Greek words defined (e.g., \"Sheol\", \"Logos\")\n  ManuscriptOrVersion // e.g., Septuagint, Vulgate, Targum\n\n  Unknown             // Use ONLY for UNRESOLVED_PRONOUNs\n}\n\n// 2. The Entity Structure\n// 👇 NEW: Helper Enum for Disambiguation\nenum BiblicalEra {\n  OldTestament\n  NewTestament\n  Intertestamental\n  ChurchHistory\n  NotApplicable\n}\n\nclass GillEntity {\n  name string @description(\"The entity name as it appears\")\n  category EntityCategory @description(\"The category this entity belongs to\")\n\n  // 👇 CRITICAL FOR DISAMBIGUATION (The \"Joseph\" Fix)\n  biblical_era BiblicalEra @description(\"If a person, which era do they belong to? Use NotApplicable for concepts.\")\n  role string? @description(\"Specific role to distinguish same-named figures (e.g., 'Patriarch', 'Apostle', 'Husband of Mary').\")\n\n  description string? @description(\"A short 5-10 word context.\")\n\n  // NOTE: `normalized_name` is intentionally NOT extracted by the LLM (see ADR-0005).\n  // Cross-page consistency on canonicalization is a property no model can guarantee\n  // across thousands of independent calls; code computes it deterministically downstream\n  // from `name` (via `search_key` in the Weaviate schema).\n}\n\n// 👇 NEW: Wrapper Class to catch Scripture Links\nclass ExtractionResult {\n  entities GillEntity[]\n  cross_references string[] @description(\"List of other Bible verses referenced in this text, normalized to 'BOOK_CH_VS' (e.g., 'ISA_53_06').\")\n}\n\n// 3. The Extraction Function\nfunction ExtractGillKnowledge(commentary_text: string, previous_entities: string?) -> ExtractionResult {\n  client OpenRouterText\n  \n  prompt #\"\n    Analyze this commentary by John Gill. Extract key entities and scripture references.\n\n    Your job is **semantic extraction only** — identify entities as they appear in the text\n    and classify them. Do NOT attempt to canonicalize names, merge variants across pages, or\n    produce a \"normalized\" form. That work is handled deterministically by code downstream.\n    Extract the entity name **as it appears in this specific passage**.\n\n    **CRITICAL DISTINCTIONS:**\n    - 'BiblicalFigure': People who appear IN the Bible narrative (Abraham, Moses, Peter, Jesus, etc.)\n    - 'CitedAuthority': Scholars, Rabbis, or historians that GILL QUOTES (Josephus, Maimonides, Jerome, etc.)\n    - 'OriginalWord': Hebrew or Greek words that Gill defines or explains (mark the transliterated word)\n    - 'Location': Physical places mentioned\n    - 'TimePeriod': Historical periods or eras\n    - 'Doctrine': Theological concepts (Justification, Election, Trinity, etc.)\n    - 'Heresy': False teachings Gill refutes\n    - 'TypeOrSymbol': Biblical types/symbols (The Rock = Christ, Manna = Word of God, etc.)\n    - 'HistoricalFigure': Non-biblical historical persons mentioned\n    - 'PeopleGroup': Ethnic or religious groups (Pharisees, Sadducees, Chaldeans, etc.)\n    - 'ManuscriptOrVersion': Biblical manuscripts or versions (Septuagint, Vulgate, Targum, etc.)\n\n    **DISAMBIGUATION (the \"Joseph fix\"):**\n    For common names (Mary, Joseph, John, James, Saul), you MUST fill the 'biblical_era' and 'role' fields accurately so downstream code can distinguish same-named figures.\n    - Example: \"Joseph was sold\" -> era: OldTestament, role: \"Patriarch/Son of Jacob\"\n    - Example: \"Joseph took the child\" -> era: NewTestament, role: \"Husband of Mary\"\n    - **INTRA-ERA COLLISIONS:** If a name refers to multiple people in the SAME era (multiple Zechariahs in OT, multiple Marys in NT), specify their distinct identity in 'role'.\n      - GOOD: name=\"Zechariah\", role=\"Prophet / Son of Berechiah\"\n      - GOOD: name=\"Zechariah\", role=\"Priest / Son of Jehoiada\"\n    - **TYPOLOGY:** Gill frequently compares OT figures to NT figures. If \"Joseph\" (NT) appears inside commentary on \"Joseph\" (OT), extract them as TWO SEPARATE entities.\n\n    **CRITICAL RULE: SCRIPTURE CITATIONS VS. ENTITIES**\n    Gill frequently abbreviates Bible books (e.g., \"Rom. i. 4\", \"Mark xvi. 11\").\n\n    1. **CHECK THE PATTERN:** Does the \"Name\" look like a book abbreviation followed by numbers (Roman or Digit)?\n       - \"Rom. i. 4\" -> This is a CITATION.\n       - \"Mark xvi. 11\" -> This is a CITATION.\n       - \"Mark\" (alone) -> This is a BIBLICAL FIGURE.\n\n    2. **THE ACTION:**\n       - If it is a CITATION: Add it to the 'cross_references' list. **DO NOT** create a GillEntity for it.\n       - If it is a PERSON: Create a GillEntity with category 'BiblicalFigure'.\n\n    **SCRIPTURE REFERENCES:**\n    - Extract any direct bible verses Gill cites to support his argument.\n    - Normalize them to the format: BOOK_CHAPTER_VERSE (e.g., MAT_03_16).\n\n    **PRONOUN RESOLUTION:**\n    If the text relies on pronouns ('he', 'they', 'the king') rather than explicit names, review the `previous_entities` list provided below.\n    - If context clearly aligns the pronoun with a previous entity, extract that specific name.\n    - **IF AND ONLY IF** you cannot confidently resolve the pronoun using the provided context, return the exact string \"UNRESOLVED_PRONOUN\" as the `name` of a Theological Entity.\n\n    Previous Entities (Context Hint):\n    {{ previous_entities }}\n\n    Commentary Text:\n    {{ commentary_text }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "main.baml": "// BAML configuration for OCR metadata validation with Ollama\n\n// Define the metadata structure\nclass Metadata {\n  book_name string? @description(\"The name of the book of the bible found at the top center of the image\")\n  chapter int? @description(\"The chapter number (converted from Roman numerals to decimal). For chapter-spanning pages, this is the first chapter.\")\n  verse string? @description(\"The verse number, range (e.g. '1-3'), list (e.g. '1,2,3'), or chapter-spanning notation\")\n  page_number int? @description(\"The page number found at top left or top right\")\n  no_verse_markers bool? @description(\"Set to true ONLY if there are NO verse (Ver.) markers on this page except in header.\")\n}\n\n// Define the core metadata structure (split validation step 1)\nclass MetadataCore {\n  book_name string? @description(\"The name of the book of the bible found at the top center of the image\")\n  chapter int? @description(\"The chapter number (converted from Roman numerals to decimal). For chapter-spanning pages, this is the first chapter.\")\n  page_number int? @description(\"The page number found at top left or top right\")\n}\n\n// Define the verse metadata structure (split validation step 2)\nclass MetadataVerses {\n  verse string? @description(\"The verse number, range (e.g. '1-3'), list (e.g. '1,2,3'), or chapter-spanning notation\")\n  no_verse_markers bool? @description(\"Set to true ONLY if there are NO verse (Ver.) markers on this page except in header.\")\n}\n\n// Define the extracted text structure for OpenRouter\nclass ExtractedText {\n  text string @description(\"The extracted text from the image\")\n}\n\n// Define the Ollama client using OpenAI-compatible endpoint\nclient<llm> Ollama {\n  provider openai\n  options {\n    model \"qwen2.5vl:32b\"\n    base_url \"http://192.168.1.188:11434/v1\"\n    //model \"qwen3-vl-8k:32b\"\n    //base_url \"http://192.168.1.179:11434/v1\"\n    api_key \"ollama\"\n    temperature 0.1\n    options: {\n      num_ctx: 2048\n    }\n  }\n}\n\n// Define the Ollama client for oss-gpt:20b (text normalization)\nclient<llm> OllamaGPT {\n  provider openai\n  options {\n    model \"qwen3-8k:32b\"\n    base_url \"http://192.168.1.188:11434/v1\"\n    api_key \"ollama\"\n    temperature 0.1\n  }\n}\n\n// Define the OpenRouter client\nclient<llm> OpenRouter {\n  provider openai\n  options {\n    base_url \"https://openrouter.ai/api/v1\"\n    api_key env.OPENROUTER_API_KEY\n    model \"qwen/qwen3-vl-235b-a22b-thinking\"\n  }\n}\n\n// Define the OpenRouter client for text-only tasks\nclient<llm> OpenRouterText {\n  provider openai\n  options {\n    base_url \"https://openrouter.ai/api/v1\"\n    api_key env.OPENROUTER_API_KEY\n    model \"x-ai/grok-4.20\"\n  }\n}\n\n// Bounded retry for TRANSPORT faults, added 2026-10-04 after one scored eval arm was voided\n// by a single truncated HTTP response body:\n//   reqwest::Error { kind: Request, url: \"http://localhost:4000/v1/chat/completions\",\n//                    source: hyper::Error(IncompleteMessage) }\n// One request in 67. The expansion stage was healthy and the model was fine; the body did not\n// arrive whole. Before this policy existed there was NO retry anywhere in baml_src, so a\n// truncated body was an unretried hard failure on the expansion path -- in production as well\n// as in evals, where retrieval silently degrades to the raw query and the user is told nothing.\n//\n// BOUNDED on purpose: 3 retries, so at most 4 attempts. A retry that can loop silently is the\n// same defect under a new name.\n//\n// IN THIS RELEASE THE BOUND IS DECLARED BUT NOT OBSERVED. body-path's backend/stage_health.py\n// reads the attempt count off the BAML collector (len(log.calls) - 1) and keeps a\n// bound_exhausted counter; neither that reader nor any consumer of it exists in 0.3.2, so here\n// a call that burned all four attempts and then failed is indistinguishable in stage_health\n// from one that failed on its first try. What this buys production is the retry itself, not\n// evidence about it. Tracked as docs/defects/D-003 for 0.3.3.\nretry_policy BoundedTransport {\n  max_retries 3\n  strategy {\n    type exponential_backoff\n    delay_ms 200\n    multiplier 2\n    max_delay_ms 2000\n  }\n}\n\n// Define the LiteLLM proxy client (routes to local Ollama/gemma4 via cluster DNS)\nclient<llm> LocalRouter {\n  provider openai\n  retry_policy BoundedTransport\n  options {\n    base_url env.LITELLM_PROXY_URL\n    api_key \"anything\"\n    model \"local-router\"\n    temperature 0.0\n  }\n}\n\n// Define the validation function (LEGACY / MONOLITHIC)\nfunction ValidateOCRMetadata(\n  image: image,\n  ocr_metadata: Metadata,\n  body_verses: string?\n) -> Metadata {\n  client Ollama\n  \n  prompt #\"\n    Please check the OCR metadata returned below for accuracy in the reported page number, book, chapter and verse this image is referring to. These will all be found at the top of the image. The page number will be either on the top far left or top far right. The book will be in the top center. And the chapter and verse will be on the opposite side of the page number in the format of 'CH. <roman numeral chapter> V. <verse number, range or list>'. Numbers should be converted to decimal. Be careful to interpret numbers properly because the font used is curly and thus 2 is often confused for 9. Verses can also be derived from the references in the text body which look like 'Ver. <verse number>'.\n    \n    VERSE FORMATTING:\n    - Single verse: \"3\"\n    - Range: \"3-5\" (verses 3 through 5)\n    - List: \"3,4,5\" (specific verses)\n    - Chapter-spanning: \"27:42-46,28:1\" (verses 42-46 of chapter 27, then verse 1 of chapter 28)\n    \n    CHAPTER-SPANNING PAGES:\n    Some pages span multiple chapters. The header will show two chapter markers:\n    \"CH. XXVII. V. 42-46. XXVIII. V. 1\" should be formatted as \"27:42-46,28:1\"\n    For chapter-spanning pages, set the chapter field to the FIRST chapter number (27 in this example).\n    \n    Current OCR Metadata:\n    - Book: {{ ocr_metadata.book_name }}\n    - Chapter: {{ ocr_metadata.chapter }}\n    - Detected Header Verses: {{ ocr_metadata.verse }}\n   {% if body_verses %}\n    - Detected Body Verses: {{ body_verses }}\n   {% endif %}\n    - Page: {{ ocr_metadata.page_number }}\n       \n    Please review the image and provide the corrected metadata if any errors are found. If the OCR is correct, return the same values. Pay special attention to:\n    1. Distinguishing between 2 and 9 in the curly font\n    2. Correctly parsing chapter-spanning headers into the chapter:verse notation\n    3. Ensuring the chapter field reflects the first chapter in chapter-spanning pages\n    {% if body_verses %}\n    4. Reconciling header range with detected body verses by using these body verses as a strong hint. \n      - If the header says \"10-15\" but body verses are exactly \"10, 11, 12, 13\" (and page layout suggests end of section), the header might be wrong or reading a smudge.\n      - If the body verses are sequential and consistent, favor them over a mismatched header.\n    {% endif %}\n    \n    {{ _.role(\"user\") }}\n    {{ image }}\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// Define the validation function (STEP 1: CORE METADATA)\nfunction ValidateMetadataCore(\n  image: image,\n  ocr_metadata: MetadataCore\n) -> MetadataCore {\n  client Ollama\n  \n  prompt #\"\n    Please check the OCR metadata returned below specifically for the PAGE NUMBER, BOOK NAME, and CHAPTER NUMBER.\n    \n    LOCATION:\n    - Page Number: Top far left OR top far right.\n    - Book Name: Top center.\n    - Chapter Number: Opposite side of page number, usually \"CH. <Roman Numeral>\".\n    \n    INSTRUCTIONS:\n    - Return the corrected values if possible.\n    - Distinguish between 2 and 9 carefully (curly font).\n    - Convert Roman numerals to decimal (e.g. XXVII -> 27).\n    - If the page spans multiple chapters (e.g. \"CH. XXVII... XXVIII\"), use the FIRST chapter number.\n    \n    Current OCR Metadata:\n    - Book: {{ ocr_metadata.book_name }}\n    - Chapter: {{ ocr_metadata.chapter }}\n    - Page: {{ ocr_metadata.page_number }}\n    \n    {{ _.role(\"user\") }}\n    {{ image }}\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// Define the validation function (STEP 2: VERSES)\nfunction ValidateMetadataVerses(\n  image: image,\n  chapter: int?,\n  verse_hint: string?,\n  body_verses: string?\n) -> MetadataVerses {\n  client Ollama\n  \n  prompt #\"\n    Please check the OCR metadata returned below for accuracy by identifying the VERSE RANGE described in the header of this image.\n    \n    LOCATION:\n    - Usually \"V. <number>\", \"V. <start>-<end>\", or similar.\n    - Found near the Chapter number in the header.\n    \n    VERSE FORMATTING:\n    - Single verse: \"3\"\n    - Range: \"3-5\"\n    - List: \"3,4,5\"\n    - Chapter-spanning: \"27:42-46,28:1\"\n    \n    INSTRUCTIONS:\n    1. Read the header verse notation carefully since it uses a curly font. distinguish 2 vs 9.\n    2. If the page spans chapters (e.g. \"CH. 27 V. 40 ... CH. 28 V. 1\"), use the chapter-spanning notation.\n    3. Use the provided Body Verses as a strong hint for what verses are actually discussed on the page.\n    4. ALWAYS convert Roman numerals to decimal numbers. (e.g. 'IV' -> '4'). Never return Roman numerals.\n    \n    EXAMPLES:\n    - \"CH. IV. V. 1-7\" -> \"4:1-7\"\n    - \"CH. III. V. 34, 35, IV. V. 1\" -> \"3:34,35,4:1\"\n    \n    CONTEXT:\n    - Chapter: {{ chapter }}\n    - OCR Header Verse Hint: {{ verse_hint }}\n    {% if body_verses %}\n    - Detected Body Verses: {{ body_verses }}\n    {% endif %}\n    \n    {{ _.role(\"user\") }}\n    {{ image }}\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// Define the image text extraction function for OpenRouter\nfunction ExtractTextFromImage(\n  image: image,\n  book: string?,\n  chapter: string?,\n  verse: string?,\n  page_number: string?,\n  hebrew_text: string?,\n  greek_text: string?,\n  ocr_text: string?\n) -> string {\n  client OpenRouter\n  \n  prompt #\"\n    Extract the text from the image in markdown format. Some words might be in Greek, Hebrew or Arabic, especially in footnotes, please include these words in their proper language. Please link the footnote to its place in the text.\n    \n    IMPORTANT: The image has TWO COLUMNS but you must MERGE them into a SINGLE continuous text output. Read the left column completely from top to bottom first, then continue with the right column from top to bottom. Handle text that is hyphenated from one column to the other by combining the hyphenated word. Do NOT preserve the two-column layout in your output - provide a single flowing text.\n    \n    FOOTNOTES: The footnotes ONLY use lower case lettering (a, b, c, etc.). There can be duplicate footnote letters when they are reused in different paragraphs. Include all footnotes at the end of their respective paragraph or section, properly linked with their lowercase letter markers.\n    \n    {% if ocr_text %}\n    The output of an OCR tool is attached below and should be ONLY used to maintain accuracy in matching the original word for word since it gets some words wrong. The OCR often fails to detect the footnote lettering. OCR also struggles with the languages so use the image for those.\n    {% endif %}\n    \n    {% if hebrew_text %}\n    Original Hebrew verse the commentary is referring to is provided as a reference to ensure the Hebrew in the text is properly interpreted. Please match the Hebrew letter order as it is in the image and reference.\n    {% endif %}\n    \n    {% if greek_text %}\n    Original Greek verse the commentary is referring to is provided as a reference to ensure the Greek in the text is properly interpreted. Please match the Greek letter order as it is in the image and reference.\n    {% endif %}\n    \n    {% if book or chapter or verse or page_number %}\n    \n    === METADATA ===\n    {% if book %}Book: {{ book }}\n    {% endif %}{% if chapter %}Chapter: {{ chapter }}\n    {% endif %}{% if verse %}Verse(s): {{ verse }}\n    {% endif %}{% if page_number %}Page Number: {{ page_number }}\n    {% endif %}{% endif %}\n    \n    {% if hebrew_text %}\n    \n    === ORIGINAL HEBREW VERSES ===\n    {{ hebrew_text }}\n    {% endif %}\n    \n    {% if greek_text %}\n    \n    === ORIGINAL GREEK VERSES ===\n    {{ greek_text }}\n    {% endif %}\n    \n    {% if ocr_text %}\n    \n    === OCR OUTPUT (For Reference Only) ===\n    {{ ocr_text }}\n    {% endif %}\n    \n    {{ _.role(\"user\") }}\n    {{ image }}\n  \"#\n}\n\n// Define the verse chunk structure for alignment\nclass VerseChunk {\n  verse_ref string @description(\"Standardized verse reference, e.g., 'MAT 03:16'. Use 3-letter book codes (GEN, EXO, MAT, etc.)\")\n  start_phrase string @description(\"Unique starting phrase of the commentary for this verse (approx 5-10 words). Must be verbatim from the text.\")\n  end_phrase string @description(\"Unique ending phrase of the commentary for this verse (approx 5-10 words). Must be verbatim from the text.\")\n}\n\n// Define the verse extraction function\nfunction ExtractVersesFromMarkdown(\n  markdown_text: string\n) -> VerseChunk[] {\n  client OpenRouterText\n  \n  prompt #\"\n    Analyze the following commentary text and split it into verse chunks. Each chunk corresponds to a specific verse reference (e.g., \"Ver. 1.\", \"Ver. 2.\").\n    \n    CRITICAL: You must extract EVERY single verse found in the text. Do not skip any.\n    \n    - Look for explicit markers like \"Ver. 31.\"\n    - If there is text before the first explicit marker that belongs to a previous verse, extract it as a separate chunk and infer the verse reference (e.g., if \"Ver. 31\" follows, the previous text is likely \"Ver. 30\").\n    - Do not stop after the first verse. Process the entire text.\n    \n    For each verse chunk:\n    1. Identify the verse reference. Convert it to a standardized format (e.g., \"GEN 01:01\").\n    2. Extract the first 10-15 words IMMEDIATELY after the verse marker (e.g., \"Ver. 31.\") as the `start_phrase`. This often includes the QUOTED VERSE TEXT (which may be in italics or marked with * or brackets) followed by commentary. DO NOT skip the verse quotation.\n    3. Extract the last 10-15 words of the commentary text for that verse as the `end_phrase`.\n    \n    CRITICAL: The `start_phrase` and `end_phrase` MUST be EXACT substrings from the provided text. Do not paraphrase or modify them. They will be used for fuzzy matching against the original OCR data.\n    \n    If a chunk covers multiple verses (e.g., \"Ver. 4, 5.\"), create a separate entry for each verse if possible, or one entry with the combined range if the text is merged. Ideally, split them if the text clearly delineates them. If the text is a single block for multiple verses, use the range in the ref (e.g., \"GEN 01:04-05\").\n    \n    Input Text:\n    {{ markdown_text }}\n    \n    {{ _.role(\"user\") }}\n    Extract the verse chunks.\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// Define the markdown normalization function for John Gill Commentary\nfunction NormalizeGillMarkdown(raw_markdown: string) -> string {\n  client OllamaGPT\n  \n  prompt #\"\n    You are a specialized theological editor responsible for formatting John Gill's Bible Commentary.\n    \n    Objective: Normalize the raw OCR text into clean, structured Markdown while strictly preserving the 18th-century stylistic conventions (specifically the Verse Lemma format).\n    \n    Input: Raw Markdown text derived from OCR/Vision models (which may contain page headers, varying footnote markers, and layout artifacts).\n    Output: Clean, consistent Markdown ready for database ingestion.\n    \n    === 1. STRUCTURAL RULES (STRICT) ===\n    \n    A. Remove ONLY Metadata Headers (at the very top of the page):\n    - Page numbers (e.g., \"90\", \"page 90\")\n    - Book/chapter markers like \"GENESIS\", \"CH. I. V. 3\"\n    - These are typically short lines at the very beginning, NOT part of the commentary.\n    \n    B. PRESERVE ALL Commentary Text:\n    - CRITICAL: Text that starts mid-sentence (spillover from previous page) MUST be preserved.\n    - Example: If the file starts with \"triarchs: but yet such a variety...\" this is continuation text from the previous page and MUST be kept.\n    - Only remove obvious page metadata, never remove actual commentary content.\n    \n    C. Chapter Headings:\n    - Format Chapter starts as a standard Markdown Header 1.\n    - Input: **CHAP. I.** or CHAP. 1.\n    - Output: # Chapter 1\n    \n    D. Verse Commentary (The Lemma Style):\n    - Constraint: Do NOT use ### Verse 3. Keep the archaic format.\n    - Format: Start every verse commentary on a new line with the exact pattern: Ver. {number}.\n    - Normalization:\n      - If input is V. 6., change to Ver. 6.\n      - If input is Verse 6., change to Ver. 6.\n      - If input is Ver 6, change to Ver. 6. (ensure periods are present).\n    - The Lemma: Ensure the bracketed lemma text follows immediately.\n      - Example: Ver. 6. And Jesus went, &c.]\n    \n    E. Paragraphs:\n    - Remove excessive newlines. Paragraphs should be separated by a single blank line.\n    \n    === 2. FOOTNOTE NORMALIZATION RULES (CRUCIAL) ===\n    \n    The raw text uses inconsistent markers (e.g., ^a^, ᵃ, (1), *, †, <sup>). You must standardize them to Markdown.\n    \n    CRITICAL: Do NOT invent or add new footnote markers. Only normalize markers that ALREADY EXIST in the original text.\n    \n    A. In-Text Markers:\n    - Convert EXISTING footnote markers in the body text to standard numerical Markdown citations: [^1], [^2], [^3].\n    - Number them sequentially starting from 1 for the page.\n    - Example: \"...as Aben Ezra observes^a^\" → \"...as Aben Ezra observes[^1]\"\n    - If there is NO footnote marker in the original (e.g., \"Aben Ezra observes\" with no ^a^ or superscript), do NOT add one.\n    \n    B. Footnote Definitions:\n    - Move ALL footnote definitions to the very bottom of the text.\n    - Format them as: [^1]: {Content}\n    - Matching: You must intelligently match the in-text marker to the correct definition based on context or the original marker symbol (e.g., if text has ^a^ and footer has a Vid. Josephus, link them as [^1]).\n    - Formatting: Remove the original marker letters (a, b, *) from the definition text.\n      - Bad: [^1]: a Vid. Josephus...\n      - Good: [^1]: Vid. Josephus...\n    - New section markers should start with letter 'a' unless the conversion interpreted them wrong. Spill over markers will follow the lettering order from the previous page potentially resulting in duplicate letters. BE CAREFUL to match them correctly.\n    \n    === 3. CONTENT INTEGRITY RULES ===\n    \n    - Hebrew/Greek: NEVER alter or remove Hebrew, Greek, or Arabic text. Keep it exactly as is.\n    - Italics: Ensure Bible quotations or emphasized words use *asterisks* (not _underscores_).\n    - Spelling: Do not modernize 18th-century spelling (e.g., \"shewn\", \"hath\")\n    - Spillover Text: ALWAYS preserve text that continues from a previous page, even if it starts mid-sentence.\n    \n    {{ _.role(\"user\") }}\n    \n    Please normalize the following raw OCR markdown:\n    \n    {{ raw_markdown }}\n  \"#\n}\n",
    "query_router.baml": "// BAML Schema for Query Expansion and Routing\n\nclass OptimizedQuery {\n    expanded_search_terms string @description(\"MUST begin with the user's original query verbatim, then a comma-separated list of 18th-century theological synonyms John Gill would use for the same subject. E.g. 'Rapture' -> 'Rapture, the coming of Christ, the gathering of the saints, the resurrection'.\")\n    official_entities string[] @description(\"Entities from the provided list whose subject matches the query. Empty list only if none genuinely match.\")\n}\n\nfunction OptimizeSearchQuery(user_query: string, available_entities: string[]) -> OptimizedQuery {\n  client LocalRouter\n  prompt #\"\n    You translate a modern search query into terms John Gill (18th-c. Calvinist Baptist) would use in his commentary.\n\n    Two tasks:\n    1. EXPAND: restate the query verbatim, then add comma-separated 18th-century synonyms for the same subject.\n    2. MAP: from the entity list below, return those whose subject matches the query (empty list only if none match).\n\n    Examples:\n    - 'Rapture' -> 'Rapture, the coming of Christ, the gathering of the saints, the resurrection'\n    - 'keeping the sabbath' -> 'keeping the sabbath, the Lord's day, the Christian sabbath, sabbath rest, the fourth commandment'\n    - For a person Scripture leaves unnamed (the Magi, the rich man in Lazarus's parable, Pharaoh's daughter), also add tradition terms. E.g. 'the Magi' -> 'the Magi, the wise men, the three kings, named in tradition, Gaspar Melchior Balthasar'. This applies ONLY to unnamed biblical figures — never to named people or to doctrines.\n\n    Output only the raw JSON object, starting with { and ending with }. No markdown, no preamble.\n\n    Map against these entities:\n    {{ available_entities }}\n\n    Expand and map THIS query:\n    <query>{{ user_query }}</query>\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "resolution.baml": "// BAML Schema for Page Boundary Pronoun Resolution\n// Resolves \"He\"/\"They\" across physical page splits by looking at previous context\n\nclass ResolvedPronoun {\n    resolved_entity_names string[] @description(\"The actual names of the entities that the pronoun refers to, selected strictly from the previous_entities list.\")\n}\n\nfunction ResolveBoundaryPronouns(unresolved_text: string, previous_text: string, previous_entities: string[]) -> ResolvedPronoun {\n  client OpenRouterText\n  prompt #\"\n    You are an expert in John Gill's 18th-century theological writings.\n    We have a text chunk that starts with an unresolved pronoun (like \"He\", \"They\", or \"The Apostle\") because it was split across a physical page boundary.\n\n    PREVIOUS PAGE CONTEXT:\n    {{ previous_text }}\n\n    ENTITIES MENTIONED ON PREVIOUS PAGE:\n    {{ previous_entities }}\n\n    CURRENT TEXT (STARTS WITH PRONOUN):\n    {{ unresolved_text }}\n\n    Identify who the pronouns in the CURRENT TEXT are referring to, based on the PREVIOUS PAGE CONTEXT.\n    Return ONLY the exact entity names from the provided list. If none match, return an empty list.\n    {{ ctx.output_format }}\n  \"#\n}\n\n// -----------------------------------------------------------------------------\n// Quote Repair (ADR-0006 follow-up): when verbatim verification fails on a\n// model-produced quote (it paraphrased, added words, dropped words), find the\n// substring of the source that the model was paraphrasing and return it\n// verbatim. The bot then substitutes the verbatim text into the answer so the\n// user sees Gill's actual words rather than the model's drift.\n//\n// This is the LLM-side fallback for the hybrid repair pipeline; difflib runs\n// first for the simple cases (small word edits) and only ambiguous cases reach\n// here. LocalRouter is used for speed/cost — the task is small and constrained.\n// -----------------------------------------------------------------------------\n\nclass RepairedQuote {\n    repaired_quote string? @description(\"The substring of the source text that the model was paraphrasing, returned VERBATIM with the source's original wording, punctuation, capitalization, and spelling. null if no clear correspondent passage exists in the source.\")\n}\n\nfunction RepairQuote(model_quote: string, source_text: string) -> RepairedQuote {\n    client LocalRouter\n    prompt #\"\n        A theological commentary AI quoted a passage from John Gill's 18th-century commentary, but its quote has drifted from the verbatim source — the AI may have paraphrased a word, dropped a word, added a clarifying prefix, or stitched two non-contiguous fragments.\n\n        Your job: identify the substring of the SOURCE TEXT that the AI was paraphrasing, and return that substring VERBATIM (character-for-character) as it appears in the source.\n\n        STRICT RULES:\n        - The repaired_quote must be a verbatim substring of the SOURCE TEXT. Do not add, remove, or substitute any characters.\n        - Do not modernize spelling. Preserve archaic forms (e.g. \"shew\", \"hath\", \"doth\").\n        - Do not change punctuation. Preserve the source's exact use of commas, semicolons, colons.\n        - Do not change capitalization.\n        - If the source has italics markers like *word* or footnote markers like [^1], INCLUDE them as they appear in source.\n        - Preserve the AI's intended span — don't return a much longer or shorter passage than they were trying to quote.\n\n        If the source contains NO substring that clearly corresponds to the AI's quote (e.g. the AI invented content not present in the source at all), set repaired_quote to null.\n\n        AI's QUOTE (potentially paraphrased):\n        {{ model_quote }}\n\n        SOURCE TEXT (verbatim Gill commentary):\n        {{ source_text }}\n\n        {{ ctx.output_format }}\n    \"#\n}\n",
}

def get_baml_files():
    return _file_map